enum class Errc : std::uint8_t {
  Ok = 0,
  Io,            // open/read/mmap failure
  UnexpectedEof, // input ended before the expected content
  BadNumber,     // a numeric field could not be parsed
  BadRecord,     // wrong number of fields / unexpected trailing data
  BadHeader,     // malformed header / keyword line
  UnknownStyle,  // unknown or ambiguous layout (e.g. LAMMPS atom style)
  CountMismatch, // number of records differs from the announced count
  IdOutOfRange,  // record id outside [1, n]
  DuplicateId,   // record id seen twice
  TooManyColumns,
  Unsupported, // valid input using a feature not implemented
  Sink,        // the consumer rejected a record
  LineTooLong, // a line does not fit in the source's fixed buffer
};

constexpr std::string_view to_string(Errc e) noexcept {
  switch (e) {
  case Errc::Ok: return "ok";
  case Errc::Io: return "i/o error";
  case Errc::UnexpectedEof: return "unexpected end of input";
  case Errc::BadNumber: return "invalid number";
  case Errc::BadRecord: return "invalid record";
  case Errc::BadHeader: return "invalid header";
  case Errc::UnknownStyle: return "unknown style";
  case Errc::CountMismatch: return "count mismatch";
  case Errc::IdOutOfRange: return "id out of range";
  case Errc::DuplicateId: return "duplicate id";
  case Errc::TooManyColumns: return "too many columns";
  case Errc::Unsupported: return "unsupported feature";
  case Errc::Sink: return "rejected by sink";
  case Errc::LineTooLong: return "line too long";
  }
  return "unknown error";
}

