// aio — character classes shared by the text layer.

namespace aio::text {

// Horizontal blanks. '\r' is treated as a blank so CRLF files parse like LF
// files (the '\r' before '\n' is skipped as trailing blank).
constexpr bool is_blank(char c) noexcept { return c == ' ' || c == '\t' || c == '\r'; }
constexpr bool is_eol(char c) noexcept { return c == '\n'; }
constexpr bool is_space(char c) noexcept { return is_blank(c) || is_eol(c) || c == '\v' || c == '\f'; }
constexpr bool is_digit(char c) noexcept { return static_cast<unsigned char>(c - '0') < 10; }
constexpr char to_lower(char c) noexcept { return (c >= 'A' && c <= 'Z') ? char(c + 32) : c; }

// Character-set predicate usable as a template argument / functor.
template <char... C>
struct CharSet {
  constexpr bool operator()(char c) const noexcept { return ((c == C) || ...); }
};

using Blanks = CharSet<' ', '\t', '\r'>;
using Spaces = CharSet<' ', '\t', '\r', '\n', '\v', '\f'>;
using Comma = CharSet<','>;
using Colon = CharSet<':'>;
using Semicolon = CharSet<';'>;
using Equal = CharSet<'='>;
using DoubleQuote = CharSet<'"'>;
using Hash = CharSet<'#'>;

} // namespace aio::text
